import java.nio.file.*;import java.io.*;import org.apache.batik.transcoder.*;import org.apache.batik.transcoder.image.PNGTranscoder;
public class RenderIcons{public static void main(String[] args)throws Exception{try(var files=Files.list(Path.of(args[0]))){for(Path p:files.filter(x->x.toString().endsWith(".svg")).toList()){var t=new PNGTranscoder();t.addTranscodingHint(PNGTranscoder.KEY_WIDTH,256f);t.addTranscodingHint(PNGTranscoder.KEY_HEIGHT,256f);try(var out=Files.newOutputStream(Path.of(p.toString().replace(".svg",".png")))){t.transcode(new TranscoderInput(p.toUri().toString()),new TranscoderOutput(out));}}}}}
